89:/**
90: * The authorization question that names no country — the one the model was
91: * answering, and getting backwards.
92: *
93: * Airbnb via Greenhouse asks "Are you legally authorized to work in the country
94: * where the job is located?". It matches neither the US pattern nor a residence
95: * question, so until 2026-08-19 there was no default and the model wrote one:
96: * "Yes", three times, into a bank whose approved row said "No — I hold a B1/B2
97: * visitor visa and have no US work authorization". Nothing was submitted with
98: * it only because a verification gate happened to stop those runs first.
99: *
100: * The country is not unknowable here — it is the posting's. So the answer is
101: * resolved from the posting's reach against the candidate's own work
102: * countries, and never from a model.
103: */
104:describe("conservativeDefaultAnswer: authorization where the job is located", () => {
105:  const BRAZIL = { workCountries: ["Brazil"] };
106:  const ASKED = [
107:    "Are you legally authorized to work in the country where the job is located?",
108:    "Are you legally authorized to work in the country where this position is located? *",
109:    "Are you authorized to work in the country of the employer?",
110:  ];
111:
112:  it.each(ASKED)("answers no for a US posting: %s", (q) => {
113:    const d = conservativeDefaultAnswer(q, {
114:      location: "San Francisco, CA, United States",
115:      ...BRAZIL,
116:    });
117:    expect(d).not.toBeNull();
118:    expect(d!.answer).toMatch(/^No/);
119:    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
120:  });
121:
122:  it("answers no for a posting based where the candidate cannot work", () => {
123:    // Berlin: as false to claim as the US, and the model would have said yes.
124:    const d = conservativeDefaultAnswer(ASKED[0], {
125:      location: "Berlin/Remote",
126:      ...BRAZIL,
127:    });
128:    expect(d!.answer).toMatch(/^No/);
129:  });
130:
131:  it("answers yes when the posting reaches a country the candidate may work in", () => {
132:    // The negative is conservative, not automatic: on a worldwide-remote role
133:    // the candidate IS authorized where the work happens, and answering "no"
134:    // would throw away a job he can legally take.
135:    const d = conservativeDefaultAnswer(ASKED[0], {
136:      location: "Anywhere in the World",
137:      remoteScope: "worldwide",
138:      ...BRAZIL,
139:    });
140:    expect(d!.answer).toMatch(/^Yes/);
141:    expect(resolveBooleanAnswer(d!.answer)).toBe("yes");
142:  });
143:
144:  it("answers yes for a posting in the candidate's own country", () => {
145:    const d = conservativeDefaultAnswer(ASKED[0], {
146:      location: "São Paulo, Brazil",
147:      ...BRAZIL,
148:    });
149:    expect(d!.answer).toMatch(/^Yes/);
150:  });
151:
152:  /**
153:   * The two cases 40 real postings caught that invented locations did not.
154:   *
155:   * The first pass used `reachAllows`, which answers "can this candidate take
156:   * this job" — a worldwide posting is yes there whatever its location line
157:   * says. Run against production rows on 2026-08-19 it claimed US
158:   * authorization on Atlassian (San Francisco) and Overvak (New York), which
159:   * is the exact fabrication the branch exists to stop, and denied it on three
160:   * Brazilian postings for a Brazilian candidate.
161:   */
162:  it("does not claim the US on a US posting the row calls worldwide", () => {
163:    const d = conservativeDefaultAnswer(ASKED[0], {
164:      location: "San Francisco, California, USA",
165:      remoteScope: "worldwide",
166:      ...BRAZIL,
167:    });
168:    expect(d!.answer).toMatch(/^No/);
169:  });
170:
171:  it("still says yes when a worldwide posting names no country at all", () => {
172:    const d = conservativeDefaultAnswer(ASKED[0], {
173:      location: "Remote",
174:      remoteScope: "worldwide",
175:      ...BRAZIL,
176:    });
177:    expect(d!.answer).toMatch(/^Yes/);
178:  });
179:
180:  it("answers the residence question with its own true answer", () => {
181:    // "…in the country where you reside" is a different question, and its true
182:    // answer for someone working legally where they live is yes. A blanket
183:    // negative here would be as false as the positive is for the US — and
184:    // until 2026-08-21 it got no answer at all, which under the no-wall policy
185:    // is not neutrality, it is an application that never goes out.
186:    expect(
187:      conservativeDefaultAnswer(
188:        "Are you legally authorized to work in the country in which you reside?",
189:        { location: "Remote - USA", ...BRAZIL },
190:      )?.answer,
191:    ).toMatch(/^Yes/);
192:  });
193:
194:  it("still answers the US question with the US default", () => {
195:    const d = conservativeDefaultAnswer(
196:      "Are you legally authorized to work in the United States?",
197:      {
198:        location: "Anywhere in the World",
199:        remoteScope: "worldwide",
200:        ...BRAZIL,
201:      },
202:    );
203:    // Even on a worldwide posting: the question names the US, and the answer
204:    // about the US does not change with where the role is advertised.
205:    expect(d!.answer).toMatch(/not authorized to work in the United States/);
206:  });
207:});
