209:/**
210: * The question that had no answer at all, from the Greenhouse form that died
211: * on it (2026-08-21). "Your country" and "the country this role is based in"
212: * are different questions, and answering the first with the second's careful
213: * negative would have been a false negative — the candidate may certainly work
214: * where they live.
215: */
216:describe("authorization in the candidate's own country", () => {
217:  it.each([
218:    "Do you have authorization to live and work in your country?*",
219:    "Are you legally authorized to work in your country of residence?",
220:    "Você tem autorização para trabalhar no seu país?",
221:    "¿Tienes autorización para trabajar en tu país?",
222:  ])("answers yes to %j", (q) => {
223:    const a = conservativeDefaultAnswer(q);
224:    expect(a?.kind).toBe("boolean");
225:    expect(a?.answer).toMatch(/^Yes/);
226:  });
227:
228:  it("still answers no for the United States", () => {
229:    const a = conservativeDefaultAnswer(
230:      "Are you legally authorized to work in the United States?",
231:    );
232:    expect(a?.answer).toMatch(/^No/);
233:  });
234:});

